var lines = (payload as String splitBy "\n") filter !isEmpty(trim($))
fun parseHeader(line) = { date: "$(line[1 to 4])-$(line[5 to 6])-$(line[7 to 8])", company: trim(line[9 to 26]), batchId: trim(line[27 to 35]) }
